"use client"

import { useState, useEffect } from "react"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Textarea } from "@/components/ui/textarea"
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu"
import { Plus, Mail, UserCheck, Users, Loader2, Phone, ToggleLeft, Trash2, MoreVertical } from "lucide-react"
import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import { instituteService } from "@/lib/institute-service"

interface StaffMember {
  id: string
  userId: string
  name: string
  email: string
  phone: string | null
  userStatus: string
  staffRole: "TRAINER" | "COORDINATOR" | "OTHER"
  staffStatus: "ACTIVE" | "INACTIVE"
  joinedAt: string
  notes: string | null
}

const roleLabels: Record<string, string> = {
  TRAINER: "مدرب",
  COORDINATOR: "منسق",
  OTHER: "أخرى",
}

export default function InstituteStaff() {
  const [staff, setStaff] = useState<StaffMember[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [isAddOpen, setIsAddOpen] = useState(false)
  const [addLoading, setAddLoading] = useState(false)
  const [addError, setAddError] = useState<string | null>(null)
  const [formData, setFormData] = useState({ email: "", role: "TRAINER", notes: "" })
  const [confirmDelete, setConfirmDelete] = useState<StaffMember | null>(null)
  const [actionLoading, setActionLoading] = useState<string | null>(null)

  const loadStaff = () => {
    setLoading(true)
    setError(null)
    instituteService.getStaff()
      .then((data) => setStaff(data as StaffMember[]))
      .catch(() => setError("فشل تحميل بيانات الطاقم"))
      .finally(() => setLoading(false))
  }

  useEffect(() => { loadStaff() }, [])

  const handleAdd = async () => {
    if (!formData.email) return
    setAddLoading(true)
    setAddError(null)
    try {
      const newMember = await instituteService.addStaff({
        email: formData.email,
        role: formData.role,
        notes: formData.notes || undefined,
      })
      setStaff(prev => [newMember, ...prev])
      setIsAddOpen(false)
      setFormData({ email: "", role: "TRAINER", notes: "" })
      loadStaff()
    } catch (e: any) {
      setAddError(e?.response?.data?.message || "فشل إضافة عضو الطاقم")
    } finally {
      setAddLoading(false)
    }
  }

  const handleToggleStatus = async (member: StaffMember) => {
    setActionLoading(member.id)
    const newStatus = member.staffStatus === "ACTIVE" ? "INACTIVE" : "ACTIVE"
    try {
      await instituteService.updateStaffStatus(member.id, newStatus)
      setStaff(prev => prev.map(s => s.id === member.id ? { ...s, staffStatus: newStatus } : s))
    } catch {
      // silently fail, reload to get correct state
      loadStaff()
    } finally {
      setActionLoading(null)
    }
  }

  const handleDelete = async (member: StaffMember) => {
    setActionLoading(member.id)
    try {
      await instituteService.removeStaff(member.id)
      setStaff(prev => prev.filter(s => s.id !== member.id))
    } catch {
      loadStaff()
    } finally {
      setConfirmDelete(null)
      setActionLoading(null)
    }
  }

  const activeCount = staff.filter(s => s.staffStatus === "ACTIVE").length

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white">إدارة الطاقم</h1>
          <p className="text-gray-600 dark:text-gray-400 mt-1">إضافة وإدارة مدربي ومنسقي المعهد</p>
        </div>
        <Button onClick={() => { setAddError(null); setIsAddOpen(true) }}>
          <Plus className="h-4 w-4 ml-2" />
          إضافة عضو طاقم
        </Button>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-2">
            <CardTitle className="text-sm font-medium">إجمالي الطاقم</CardTitle>
            <Users className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{loading ? "—" : staff.length}</div>
            <p className="text-xs text-muted-foreground">عضو مسجّل</p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-2">
            <CardTitle className="text-sm font-medium">الأعضاء النشطون</CardTitle>
            <UserCheck className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{loading ? "—" : activeCount}</div>
            <p className="text-xs text-muted-foreground">عضو نشط</p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-2">
            <CardTitle className="text-sm font-medium">المدربون</CardTitle>
            <UserCheck className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">
              {loading ? "—" : staff.filter(s => s.staffRole === "TRAINER").length}
            </div>
            <p className="text-xs text-muted-foreground">مدرب في الطاقم</p>
          </CardContent>
        </Card>
      </div>

      {/* Table */}
      <Card>
        <CardHeader>
          <div className="flex items-center gap-3">
            <CardTitle>قائمة الطاقم</CardTitle>
            {!loading && (
              <Badge variant="secondary" className="font-mono">{staff.length} عضو</Badge>
            )}
          </div>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div className="flex items-center justify-center py-16 text-gray-400">
              <Loader2 className="h-6 w-6 animate-spin ml-2" />
              <span>جاري تحميل الطاقم...</span>
            </div>
          ) : error ? (
            <div className="flex flex-col items-center justify-center py-16 text-red-500 gap-2">
              <span>{error}</span>
              <Button variant="outline" size="sm" onClick={loadStaff}>إعادة المحاولة</Button>
            </div>
          ) : staff.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-16 text-gray-400 gap-3">
              <Users className="h-10 w-10" />
              <p>لم يتم إضافة أي أعضاء في الطاقم بعد</p>
              <Button variant="outline" size="sm" onClick={() => setIsAddOpen(true)}>
                <Plus className="h-4 w-4 ml-1" /> إضافة أول عضو
              </Button>
            </div>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>العضو</TableHead>
                  <TableHead>معلومات الاتصال</TableHead>
                  <TableHead>الدور</TableHead>
                  <TableHead>الحالة</TableHead>
                  <TableHead>تاريخ الانضمام</TableHead>
                  <TableHead className="w-10"></TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {staff.map((member) => (
                  <TableRow key={member.id} className={member.staffStatus === "INACTIVE" ? "opacity-60" : ""}>
                    <TableCell>
                      <div className="flex items-center gap-3">
                        <Avatar>
                          <AvatarFallback>{member.name.charAt(0)}</AvatarFallback>
                        </Avatar>
                        <p className="font-medium">{member.name}</p>
                      </div>
                    </TableCell>
                    <TableCell>
                      <div className="flex flex-col gap-1 text-sm text-gray-600 dark:text-gray-400">
                        <div className="flex items-center gap-2">
                          <Mail className="h-3 w-3" />{member.email}
                        </div>
                        {member.phone && (
                          <div className="flex items-center gap-2">
                            <Phone className="h-3 w-3" />{member.phone}
                          </div>
                        )}
                      </div>
                    </TableCell>
                    <TableCell>
                      <Badge className="bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300">
                        {roleLabels[member.staffRole] ?? member.staffRole}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      <Badge className={
                        member.staffStatus === "ACTIVE"
                          ? "bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300"
                          : "bg-gray-100 text-gray-600 dark:bg-gray-800 dark:text-gray-400"
                      }>
                        {member.staffStatus === "ACTIVE" ? "نشط" : "غير نشط"}
                      </Badge>
                    </TableCell>
                    <TableCell className="text-sm text-gray-500">
                      {new Date(member.joinedAt).toLocaleDateString("ar-SA")}
                    </TableCell>
                    <TableCell>
                      <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                          <Button variant="ghost" size="sm" disabled={actionLoading === member.id}>
                            {actionLoading === member.id
                              ? <Loader2 className="h-4 w-4 animate-spin" />
                              : <MoreVertical className="h-4 w-4" />}
                          </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end">
                          <DropdownMenuItem onClick={() => handleToggleStatus(member)}>
                            <ToggleLeft className="h-4 w-4 ml-2" />
                            {member.staffStatus === "ACTIVE" ? "تعطيل" : "تفعيل"}
                          </DropdownMenuItem>
                          <DropdownMenuItem
                            className="text-red-600 focus:text-red-600 focus:bg-red-50"
                            onClick={() => setConfirmDelete(member)}
                          >
                            <Trash2 className="h-4 w-4 ml-2" />
                            إزالة من الطاقم
                          </DropdownMenuItem>
                        </DropdownMenuContent>
                      </DropdownMenu>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>

      {/* Add Staff Dialog */}
      <Dialog open={isAddOpen} onOpenChange={setIsAddOpen}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>إضافة عضو طاقم</DialogTitle>
            <DialogDescription>أدخل البريد الإلكتروني للمدرب المسجّل لإضافته إلى طاقم المعهد</DialogDescription>
          </DialogHeader>
          <div className="space-y-4 pt-2">
            <div>
              <Label htmlFor="email">البريد الإلكتروني للمدرب *</Label>
              <Input
                id="email"
                type="email"
                placeholder="trainer@example.com"
                value={formData.email}
                onChange={(e) => setFormData(f => ({ ...f, email: e.target.value }))}
              />
            </div>
            <div>
              <Label htmlFor="role">الدور</Label>
              <Select value={formData.role} onValueChange={(v) => setFormData(f => ({ ...f, role: v }))}>
                <SelectTrigger id="role"><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="TRAINER">مدرب</SelectItem>
                  <SelectItem value="COORDINATOR">منسق</SelectItem>
                  <SelectItem value="OTHER">أخرى</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label htmlFor="notes">ملاحظات (اختياري)</Label>
              <Textarea
                id="notes"
                placeholder="أي ملاحظات إضافية..."
                value={formData.notes}
                onChange={(e) => setFormData(f => ({ ...f, notes: e.target.value }))}
                rows={2}
              />
            </div>
            {addError && (
              <p className="text-sm text-red-500 bg-red-50 dark:bg-red-900/20 px-3 py-2 rounded">{addError}</p>
            )}
            <div className="flex gap-2 justify-end">
              <Button variant="outline" onClick={() => setIsAddOpen(false)} disabled={addLoading}>إلغاء</Button>
              <Button onClick={handleAdd} disabled={addLoading || !formData.email}>
                {addLoading ? <><Loader2 className="h-4 w-4 animate-spin ml-1" />جاري الإضافة...</> : "إضافة"}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>

      {/* Confirm Remove Dialog */}
      <Dialog open={!!confirmDelete} onOpenChange={() => setConfirmDelete(null)}>
        <DialogContent className="sm:max-w-sm">
          <DialogHeader>
            <DialogTitle className="text-red-600">إزالة عضو الطاقم</DialogTitle>
            <DialogDescription>
              هل أنت متأكد من إزالة <strong>{confirmDelete?.name}</strong> من طاقم المعهد؟
              <br />لن يتأثر حسابه على المنصة.
            </DialogDescription>
          </DialogHeader>
          <div className="flex justify-end gap-2 mt-2">
            <Button variant="outline" onClick={() => setConfirmDelete(null)}>إلغاء</Button>
            <Button variant="destructive" disabled={!!actionLoading} onClick={() => confirmDelete && handleDelete(confirmDelete)}>
              {actionLoading ? <Loader2 className="h-4 w-4 animate-spin" /> : "نعم، إزالة"}
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  )
}